{
  "company": "CRONUS International Ltd.",
  "messageType": "LLM.Prompt.Complete",
  "status": "Success",
  "contract": "json",
  "format": "chapters",
  "catalogue": {
    "name": "LLM.Prompt.Complete",
    "isEnabled": true,
    "filterTableNo": 0,
    "description": "Sends one prompt to a language model and returns its text answer, with no tools, record context or conversation.",
    "selectionDescription": "Read-only. Generates a text response from a prompt without tools, record context or conversation state; nothing is remembered between calls. Use a dedicated message type when one exists, and Data.Records.Get first when the prompt needs Business Central data.",
    "messageDirection": "Outbound",
    "keywords": [
      "one-shot ai completion",
      "prompt completion",
      "generate text",
      "transform text",
      "classify text",
      "extract data",
      "summarize text",
      "playbook reasoning",
      "scheduled task ai",
      "language model",
      "llm",
      "ask ai",
      "read document with ai",
      "read image with ai"
    ],
    "chargeable": true
  },
  "chapters": {
    "envelope": {
      "strict": {
        "type": "boolean",
        "required": false,
        "default": false,
        "description": "Optional root Boolean, default false. When true, unknown data keys are refused before execution with UnknownParameter. Do not place this option inside data."
      },
      "subject": {
        "use": "notUsed",
        "description": "The type addresses no record; a subject that is sent is ignored."
      },
      "dataRequired": true,
      "version": "1.0",
      "contentType": "text/json"
    },
    "parameters": [
      {
        "name": "prompt",
        "type": "string",
        "required": true,
        "description": "The user prompt sent to the language model. A value that is not a JSON string is refused with InvalidParameterFormat; an empty one with MissingParameter."
      },
      {
        "name": "system",
        "type": "string",
        "required": false,
        "description": "Optional system prompt. No Bootstrap or skill is injected, but every call starts the system text with one fresh SESSION TIME block from Foundation (now in UTC, the user's time zone, today with its weekday and, when it differs, the work date), followed by one empty line and this text. A SESSION TIME block already inside this text is replaced by the fresh one, never doubled. There is no opt-out."
      },
      {
        "name": "attachments",
        "type": "array",
        "required": false,
        "description": "Files uploaded to Foundation staging, in order. Each entry has exactly one key, stagingId. The caller-owned upload is consumed in this transaction. Supports text/*, application/pdf, image/png and image/jpeg. Total bytes must fit the language model Attachment Limit Bytes (0 uses 100 MB). Invalid uploads never call the model or incur a provider charge. Upload again after a refusal.",
        "children": [
          {
            "name": "stagingId",
            "type": "string",
            "required": true,
            "description": "The GUID returned when the caller uploaded the file to Foundation staging."
          }
        ]
      },
      {
        "name": "roleCode",
        "type": "string",
        "required": false,
        "description": "Optional code of a Bifrost Language Model (at most 20 characters). When omitted, the caller's own language model is used, and then the default model."
      },
      {
        "name": "file",
        "type": "object",
        "required": false,
        "description": "Optional inline file sent with the prompt; takes precedence over files and attachment. A value that is not a JSON object is ignored, and files and attachment are then ignored too.",
        "children": [
          {
            "name": "data",
            "type": "string",
            "required": false,
            "description": "The file content, Base64-encoded. Send it together with mimeType."
          },
          {
            "name": "mimeType",
            "type": "string",
            "required": false,
            "description": "The MIME type, for example application/pdf or image/png. Leading and trailing spaces, letter case and parameters after a semicolon are ignored, and the normalized type is sent. For OpenAI, Azure OpenAI, Custom LLM, Anthropic, Google and xAI, image/png and image/jpeg stay inline. Any other image type is refused before sending. A decoded file larger than the language model file size limit is refused before sending. The decoded size of all files on the call cannot exceed 104857600 bytes (100 MB); a larger total is refused before sending and the error names the total and the cap. Other documents are sent inline or uploaded to that provider's file store for the duration of the call and then deleted."
          },
          {
            "name": "fileName",
            "type": "string",
            "required": false,
            "description": "The file name. Used by the providers that take a file name; the others ignore it."
          }
        ]
      },
      {
        "name": "files",
        "type": "array",
        "required": false,
        "description": "Optional inline files sent with the prompt when file is absent. Each entry is an object with data, mimeType and fileName. A non-array value is ignored and the stored attachment is not used. The total decoded size cannot exceed 104857600 bytes (100 MB).",
        "children": [
          {
            "name": "data",
            "type": "string",
            "required": false,
            "description": "The file content, Base64-encoded. Send it together with mimeType."
          },
          {
            "name": "mimeType",
            "type": "string",
            "required": false,
            "description": "The MIME type, for example application/pdf or image/png. Leading and trailing spaces, letter case and parameters after a semicolon are ignored, and the normalized type is sent. For OpenAI, Azure OpenAI, Custom LLM, Anthropic, Google and xAI, image/png and image/jpeg stay inline. Any other image type is refused before sending. A decoded file larger than the language model file size limit is refused before sending. The decoded size of all files on the call cannot exceed 104857600 bytes (100 MB); a larger total is refused before sending and the error names the total and the cap. Other documents are sent inline or uploaded to that provider's file store for the duration of the call and then deleted."
          },
          {
            "name": "fileName",
            "type": "string",
            "required": false,
            "description": "The file name. Used by the providers that take a file name; the others ignore it."
          }
        ]
      },
      {
        "name": "attachment",
        "type": "object",
        "required": false,
        "description": "Optional reference to a stored attachment whose content is sent with the prompt. Ignored when file is supplied, when table is not one of the allowed names, or when systemId is not a GUID that finds an attachment with content.",
        "children": [
          {
            "name": "table",
            "type": "string",
            "required": true,
            "description": "The table that holds the attachment.",
            "allowed": [
              "Incoming Document Attachment",
              "Document Attachment"
            ]
          },
          {
            "name": "systemId",
            "type": "string",
            "required": true,
            "description": "The SystemId (GUID) of the attachment record."
          }
        ]
      }
    ],
    "response": {
      "contentType": "text/json",
      "fields": [
        {
          "name": "status",
          "type": "string",
          "description": "Success when the provider response was returned."
        },
        {
          "name": "reply",
          "type": "string",
          "description": "The provider response text, when supplied by the provider."
        },
        {
          "name": "text",
          "type": "string",
          "description": "A copy of reply, added when the provider did not return text."
        },
        {
          "name": "type",
          "type": "string",
          "description": "The value reply. Returned by the Anthropic provider only."
        },
        {
          "name": "sessionTime",
          "type": "object",
          "description": "The clock the model was given, read from the block that was sent: nowUtc (yyyy-MM-ddTHH:mm:ssZ), workDate (yyyy-MM-dd) and timeZone (the user's time zone name; left out when Foundation does not know the zone). Left out when no block could be sent."
        },
        {
          "name": "warnings",
          "type": "array",
          "description": "Added only when something was left out without failing the call. sessionTimeUnavailable: Foundation could not supply the SESSION TIME block, so the prompt was sent without it and sessionTime is absent."
        },
        {
          "name": "usage",
          "type": "object",
          "description": "The token usage the provider reported for the call. Returned by the Anthropic provider only, and only when the provider reports usage."
        }
      ]
    },
    "errors": [
      {
        "code": "PermissionDenied",
        "error": "You do not have permission to complete prompts with a language model.",
        "when": "The caller does not hold Foundation's BIFROST Chat ori permission set. A language model whose provider is not Copilot also needs this app's BIFROST LLM Chat ori.",
        "fix": "Ask your administrator to assign the BIFROST Chat ori permission set, and BIFROST LLM Chat ori for a language model whose provider is not Copilot."
      },
      {
        "code": "MissingParameter",
        "error": "The prompt is missing.",
        "when": "prompt is missing or empty.",
        "fix": "Send the text to complete in prompt."
      },
      {
        "code": "RecordNotFound",
        "error": "Bifrost Language Model \"%1\" was not found.",
        "when": "roleCode is sent but no language model has that code.",
        "fix": "Leave roleCode out to use your own or the default language model, or use a code from the Bifrost Language Models list."
      },
      {
        "code": "PreconditionFailed",
        "error": "No language model with a chat provider is set up for you.",
        "when": "The selected, the caller's or the default language model has no usable chat provider or API key.",
        "fix": "Ask your administrator to set up a language model on the Bifrost Language Models setup page, with its API key on Bifrost App Secrets."
      },
      {
        "code": "InvalidParameterFormat",
        "error": "The prompt must be a JSON string.",
        "when": "prompt is a number, Boolean, null, object or array instead of a JSON string.",
        "fix": "Send the text to complete in prompt."
      },
      {
        "code": "PreconditionFailed",
        "error": "The language model provider refused authentication.",
        "when": "The provider returns HTTP 401 or 403. Provider error bodies are never returned or logged.",
        "fix": "Check the Base URL, model and API key setup on the Bifrost Language Model card; use Bifrost App Secrets to set the API key, then try Test Connection."
      },
      {
        "code": "Retryable",
        "error": "The language model provider is temporarily unavailable.",
        "when": "The provider returns HTTP 408, 429 or 5xx, or the request times out or cannot reach the provider.",
        "fix": "Wait and retry. If the failure persists, check the provider status and the limits on the Bifrost Language Model card."
      },
      {
        "code": "PreconditionFailed",
        "error": "HttpClient calls are blocked in this environment. An administrator must allow AL HttpClient requests.",
        "when": "Allow HttpClient Requests is disabled for the app.",
        "fix": "Ask an administrator to enable Allow HttpClient Requests for Bifrost Language Models in Extension Management, then retry."
      },
      {
        "code": "PreconditionFailed",
        "error": "The language model provider could not complete the prompt.",
        "when": "The provider refuses the request or returns an invalid response, including an unsupported file.",
        "fix": "Check the Base URL, model and API key setup on the Bifrost Language Model card; use Bifrost App Secrets to set the API key, then try Test Connection."
      },
      {
        "code": "InvalidParameter",
        "error": "This language model accepts only PNG and JPEG images.",
        "when": "The file mimeType is an image other than image/png or image/jpeg.",
        "fix": "Send a PNG or JPEG image, or send a PDF or another document instead of this image type. No request was sent."
      },
      {
        "code": "InvalidParameter",
        "error": "The file is larger than the language model file size limit.",
        "when": "The decoded file is larger than the language model file size limit.",
        "fix": "Reduce the file size. No request was sent."
      },
      {
        "code": "InvalidParameter",
        "error": "The attached files total %1 bytes, which is over the %2 byte cap.",
        "when": "The decoded size of all attached files together is larger than the total file size cap.",
        "fix": "Remove or reduce files so the total decoded size is within the cap. No request was sent."
      },
      {
        "code": "UnknownParameter",
        "error": "The attachment contains an unknown parameter.",
        "when": "An attachments entry has a key other than stagingId.",
        "fix": "Upload the file again and send its new stagingId."
      },
      {
        "code": "InvalidParameterFormat",
        "error": "The attachment must contain one stagingId GUID.",
        "when": "attachments is not an array of objects with a stagingId GUID.",
        "fix": "Upload the file again and send its new stagingId."
      },
      {
        "code": "MissingParameter",
        "error": "The attachment must contain one stagingId GUID.",
        "when": "An attachments entry has no stagingId.",
        "fix": "Upload the file again and send its new stagingId."
      },
      {
        "code": "RecordNotFound",
        "error": "The staged upload was not found.",
        "when": "An upload is unknown, owned by another user, duplicated or already consumed.",
        "fix": "Upload the file again and send its new stagingId."
      },
      {
        "code": "InvalidParameter",
        "error": "The attachment content type is not supported.",
        "when": "An attachment is not text, PDF, PNG or JPEG.",
        "fix": "Upload the file again and send its new stagingId."
      },
      {
        "code": "LimitExceeded",
        "error": "The total attachment size exceeds the language model limit.",
        "when": "The attachments total exceeds the model attachment byte limit.",
        "fix": "Send smaller files or ask your administrator to change the model attachment limit."
      },
      {
        "code": "BusinessCentralError",
        "error": "Business Central's own error text",
        "when": "An error the type does not catch is raised before the provider is called, for example a message version other than 1.0.",
        "fix": "Read the text and correct the request. Nothing was sent to the provider and nothing was changed."
      }
    ],
    "effect": {
      "effect": "read",
      "changes": "Sends the prompt, the system prompt and any file to the selected external language model provider and returns its answer; the data sent cannot be recalled and the answer can differ between calls. No Business Central business data is changed. Staged uploads supplied in attachments are consumed in the call transaction. The other write is the Last Used On stamp of the language model's API key, at most once a day, after the provider has answered. The type itself does not commit.",
      "idempotent": false,
      "permissionSet": "BIFROST Chat ori; BIFROST LLM Chat ori for non-Copilot providers",
      "preconditions": [
        "The caller holds Foundation's BIFROST Chat ori permission set, and this app's BIFROST LLM Chat ori when the language model's provider is not Copilot.",
        "The caller can read the Bifrost Language Models table.",
        "A language model with a usable chat provider is set up: the one in roleCode, otherwise the caller's own or the default language model, with its API key where the provider needs one.",
        "Outbound HttpClient requests are allowed for the app; otherwise the call is refused with PreconditionFailed."
      ]
    },
    "metering": {
      "chargeable": true,
      "chargedAs": "message"
    },
    "related": [
      {
        "name": "Data.Records.Get",
        "useInsteadWhen": "Read Business Central data first, then use the returned values in the prompt."
      },
      {
        "name": "Data.Records.Set",
        "useInsteadWhen": "Use the completion as input for structured record updates only after validating the generated values."
      },
      {
        "name": "Storage.Upload.CommitToStaging",
        "useInsteadWhen": "Put the file in Foundation staging, then send the returned stagingId in attachments."
      }
    ],
    "examples": [
      {
        "title": "Complete a prompt with the caller's own or the default model",
        "request": {
          "type": "LLM.Prompt.Complete",
          "data": {
            "prompt": "Classify the subject \"Invoice 4711 for March\" as invoice, order or other.",
            "system": "Answer with one word."
          }
        },
        "response": {
          "status": "Success",
          "reply": "invoice",
          "text": "invoice",
          "sessionTime": {
            "nowUtc": "2026-11-06T09:30:00Z",
            "workDate": "2026-11-06",
            "timeZone": "GMT Standard Time"
          }
        }
      },
      {
        "title": "Complete a prompt with a selected model",
        "request": {
          "type": "LLM.Prompt.Complete",
          "data": {
            "prompt": "Summarize this text.",
            "system": "Return one concise sentence.",
            "roleCode": "CLAUDE"
          }
        },
        "response": {
          "status": "Success",
          "reply": "A concise summary.",
          "text": "A concise summary."
        }
      },
      {
        "title": "Send an inline file with the prompt",
        "request": {
          "type": "LLM.Prompt.Complete",
          "data": {
            "prompt": "Extract the invoice number and total.",
            "file": {
              "data": "JVBERi0xLjQK",
              "mimeType": "application/pdf",
              "fileName": "invoice.pdf"
            }
          }
        },
        "response": {
          "status": "Success",
          "reply": "Invoice 4711, total 1240 EUR.",
          "text": "Invoice 4711, total 1240 EUR."
        }
      },
      {
        "title": "Send a stored incoming document attachment with the prompt",
        "request": {
          "type": "LLM.Prompt.Complete",
          "data": {
            "prompt": "Who is the vendor on this document?",
            "attachment": {
              "table": "Incoming Document Attachment",
              "systemId": "<systemId>"
            }
          }
        },
        "response": {
          "status": "Success",
          "reply": "Contoso Ltd.",
          "text": "Contoso Ltd."
        }
      }
    ],
    "overview": "Use LLM.Prompt.Complete for one-shot reasoning, transformation, extraction, classification or generation when no dedicated message type covers the task. It sends one user prompt and optional system prompt, and optionally one or more files, to a configured provider without tools, record context or conversation state, and returns the answer as text. Every call also carries the current date and time, so the prompt can say \"today\" or \"last month\". It reads and writes no Business Central records for you: read the data first and put the values in the prompt.",
    "notes": "If roleCode is omitted, the caller's configured language model is used and then the default model is tried. An inline file takes precedence over a stored attachment. OpenAI, Azure OpenAI, Custom LLM, Anthropic, Google and xAI use one file policy: the MIME type is trimmed, compared without letter case, and parameters after a semicolon are ignored, and that normalized type is sent; image/png and image/jpeg stay inline; any other image type is refused before a request is sent; a decoded file larger than the language model file size limit is refused before a request is sent; the decoded size of all files on the call cannot exceed 104857600 bytes (100 MB), and a larger total is refused before any upload or provider request with an error that names the total and the cap; a PDF or other document is sent inline when the provider accepts inline documents, otherwise it is uploaded to that provider's file store, referenced by file id, and deleted after the call, including when the prompt fails. The Copilot provider does not accept files: a call with a file answers with the provider failure (PreconditionFailed). Other providers may reject files they cannot read. A provider HTTP client error includes the HTTP status and, when the provider sends one, a short error code. Provider error text, secrets and the prompt are not returned. Provider response properties other than status, reply and text are passed through; the Anthropic provider adds type and usage. The prompt and any file leave Business Central for the provider the language model names, so send no data that provider may not receive. A document that cannot be sent inline is stored at that provider only for the duration of the call and is then deleted. Every call adds a fresh SESSION TIME block (Foundation's own text, in English, whatever the session language) in front of the system prompt, so the model knows the current UTC time, the user's time zone, today's date and weekday, and the work date when it differs; the response repeats the clock as sessionTime. If Foundation cannot supply the block the call still succeeds, without sessionTime, and warnings holds sessionTimeUnavailable. The reply is free text from an external model: validate it before it is used to change anything."
  },
  "conventions": "## Errors and warnings\r\nAn error response has `status` = `Error`, a stable `code`, the `error` text and, when they apply, `parameter` (the request parameter concerned, e.g. `lines[2].no`), `received` (the value received), `expected` (what was expected) and `nextStep` (what to do now). `hint` says where to read more.\r\nWhen a request has several problems, all of them are listed in `errors[]` - each with the same fields - under a top-level `code` (`MultipleErrors`, or a shared code such as `InvalidLine` for the `lines` of a Create type) and a summary `error`. Fix them all before calling again. One problem is reported at the top level, with no `errors[]`.\r\nRequest values are checked first and every problem found is reported together. A Business Central validation error raised afterwards, while a record is being written, stops the call and is reported on its own: `code` = `BusinessCentralError`, Business Central's own `error` text, and `parameter` naming the request parameter being applied, e.g. `lines[1].accountNo`. Nothing is written.\r\nRequest values are read in one format, whatever the language: dates `YYYY-MM-DD`; date-times ISO 8601 with `Z` or an offset; amounts as JSON numbers (or a string such as `\"1234.56\"`, no thousands separator); integers as JSON integers; booleans `true` or `false`. Any other value is `InvalidParameterFormat` with `received` and `expected`; for an unambiguous local form such as `26.09.2026`, `nextStep` gives the value to resend. Every bad value of a request is reported together.\r\nAnswers are written in one format as well, whatever the language of the call: dates `YYYY-MM-DD`, date-times ISO 8601, numbers with a dot and no thousands separator, and the option and enum values of every answer except `Data.Records.Get` and `Data.Records.Set` as their English names, so a value read from an answer can be sent back. Those two answer the caption of the language of the call, for a person to read. The language of the call (`lcid`) changes captions and message texts, not these forms. Two things are outside Bifrost's control: Business Central writes its own texts (a ledger entry description such as `Direct Cost V00010 on 10/02/26`, the text of a `BusinessCentralError`) with the regional settings of the server session, which `lcid` does not change, so a date in such a text can be in month-day order; and a table view is read with those settings too, so write dates in a view as `YYYY-MM-DD` and decimals with a dot.\r\nBoth success and error responses can carry `warnings[]`, each with `code`, `message` and, when they apply, `parameter` and `nextStep`.\r\n`UnknownParameter` refuses undeclared data keys before execution for every type whose effect is not read, including a missing effect. The root envelope option `strict:false` cannot opt out. Read types keep warnings without changing status, validationResult or domain warningCount unless the caller sets `strict:true` (next to type and subject, never inside data). Refusals list the keys and localized nextStep corrections; no business changes or successful execution charges occur. Example: {\"type\":\"Memory.User.Set\",\"strict\":true,\"data\":{\"memory\":\"test\",\"memry\":\"typo\"}} is refused.\r\n`FieldChangedByBC` is a warning from Data.Records.Set: another field validation or the write changed a sent field after its own validation. `parameter` names data[n].fields.{jsonName}, counting from 0. Status stays Success. Compare the returned values with what you sent; follow `nextStep` to use validation order or send the field again in a separate call. Normalisation of the field itself, LCY, Dimension Set ID, BLOB, Media, MediaSet and skipped fields are excluded.\r\n`SecurityFilterApplied` is a warning from Data.Records.Get, severity `low`, `parameter` `table`: a security filter of the caller applies to the table, so the result may hold fewer records than the table. `securityFiltered` is then true. Status stays Success, and the hidden records are never counted or described. Ask an administrator if you expect more records.\r\nData.RecordIds.Get, Data.Totals.Get, Data.Entries.Find and CSV.Records.Get do not return `securityFiltered` or `SecurityFilterApplied`. Their results can still be limited by security filters: counts and totals cover only visible records, and the absence of a flag or warning does not prove that every record in the table was included. Their help explains this visibility limit; request filters such as tableView and date ranges are separate.\r\nWhen a Business Central operation fails, the error can identify the request parameter being applied, the expected input and what to do next. That guidance accompanies the original `BusinessCentralError` after rollback, including a failed queued task. It does not change which writes are rolled back or committed. Guidance is cleared between messages; a message without it keeps its existing response shape. Recognized lock errors follow the `Retryable` rules below.\r\nSome message types accept calls only through a particular path: a scheduled queue message, the Task API (`/tasks`), the in-product MCP tool server, another message type, or the Messages page Run Task action. Bifrost determines where the call came from; request values cannot override it. A call through an unsupported path is refused with `PreconditionFailed` and a `nextStep` naming the path to use.\r\n`Retryable` means a transient lock or deadlock caught while writing or posting. `error` keeps Business Central's original text. `expected` is \"no concurrent lock on the same records\"; `nextStep` is \"Retry the same call after a few seconds; nothing was changed.\" Bifrost does not retry automatically. Uncaught recognized lock errors are also `Retryable` for `write` types. Uncaught `read` and `irreversible` errors remain `BusinessCentralError`, because an irreversible operation may already have committed.\r\n`ConfirmationRequired` is the preview refusal for an irreversible type called without `expectedCount`. Nothing was changed; inspect `expected` and the description before sending the same request with that count. `ConfirmationMismatch` means the count has changed or the sent count was wrong; nothing was changed. Inspect the new preview before confirming again. Feature apps use the same preview and confirmation protocol for irreversible operations.\r\nCodes: `MissingParameter`, `InvalidParameterFormat`, `InvalidParameter`, `RecordNotFound`, `AmbiguousRecord`, `ConflictingIdentifiers`, `InvalidFilterField`, `InvalidLine`, `NothingToPreview`, `LinesSkipped`, `BlockedByWriteGuard`, `PreconditionFailed`, `PermissionDenied`, `LimitExceeded`, `BusinessCentralError`, `MultipleErrors`, `DeprecatedParameter`, `UnknownParameter`, `FieldChangedByBC`, `Retryable`, `EULA_REQUIRED`, `TRIAL_NOT_STARTED`, `ConfirmationRequired`, `ConfirmationMismatch`, `SecurityFilterApplied`. The `error` text may be translated; the code never is.\r\n"
}
